mapper.select:
SELECT role FROM digital_team_project_member
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND user_id = #{userId}

SELECT user_id, role FROM digital_team_project_member
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
ORDER BY user_id

SELECT COUNT(*) FROM digital_team_project_member
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND user_id = #{userId}

mapper.update:
UPDATE digital_team_project_member SET role = #{role}, updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND user_id = #{userId}

mapper.delete:
DELETE FROM digital_team_project_member
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND user_id = #{userId}
